INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64422029', 64422029, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI PERENCANAAN PEMBANGUNAN', 'Penyediaan Jasa Konsultansi Perorangan Full Stack Developer 5', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 75900000, 'January 2026', 'APBD', 1, 1, '1 Paket', '"1. Melakukan penyusunan dokumen Software Development Life Cycle (SDLC) yang memuat planning, design, testing, building, dan deployment; 2. Melakukan koordinasi dengan stakeholder untuk memahami kebutuhan perangkat lunak yang diperlukan dalam konteks perencanaan pembangunan; 3. Membangun antarmuka pengguna (UI) yang responsif dan estetis; 4. Melakukan integrasi desain UI/UX ke dalam implementasi frontend; 5. Memelihara server, aplikasi, dan database yang diperlukan untuk mendukung solusi perangkat lunak; 6. Membuat desain dan melakukan pengelolaan struktur basis data; 7. Menyusun konsep query language basis data yang optimal dan memastikan keamanan serta integritas data dimaksud; 8. Melakukan optimalisasi kinerja aplikasi baik di sisi frontend maupun backend; 9. Menerapkan teknik caching dan optimisasi lainnya untuk meningkatkan responsivitas aplikasi; 10. Merancang dan melaksanakan uji fungsional dan uji kinerja untuk memastikan kualitas dan kestabilan perangkat lunak; 11. Melakukan debugging selama pengujian dan penggunaan perangkat lunak; 12. Melakukan pemeliharaan rutin, pembaruan, dan perbaikan pada solusi perangkat lunak yang dikembangkan; 13. Memastikan keamanan perangkat lunak memenuhi standar yang ditetapkan; 14. Mendokumentasikan kode, arsitektur, dan proses pengembangan perangkat lunak; 15. Menyusun panduan untuk pengguna dan dokumentasi teknis yang diperlukan; 16. Melakukan koordinasi dan kerja sama sebagai tim dan membantu pelaksanaan seluruh kegiatan di Pusdatinrenbang Bappeda; 17. Membuat laporan hasil pekerjaan pada setiap bulan."', 'Tenaga Ahli Tidak Ber SKA / SKK , S1 Pengalaman Minimal 6 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1554379);
