INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64422702', 64422702, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS PERUMAHAN RAKYAT DAN KAWASAN PERMUKIMAN', 'Pemetaan dan Visualisasi Lokasi Kumuh di Provinsi DKI Jakarta', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 954468032, 'February 2026', 'APBD', 0, 1, '1 Paket', 'Kegiatan Pemetaan dan Visualisasi Lokasi Kumuh di Provinsi DKI Jakarta bertujuan mengidentifikasi dan menyajikan sebaran serta kondisi permukiman kumuh secara spasial sebagai dasar perencanaan penanganan yang terarah dan terpadu. Pemetaan dilakukan untuk memperoleh gambaran tingkat kekumuhan dan karakteristik wilayah secara akurat dan mudah dipahami.', 'Kegiatan meliputi pengumpulan dan pengolahan data spasial dan nonspasial berbasis kelurahan serta pemetaan menggunakan Sistem Informasi Geografis (SIG). Output berupa peta tematik dan visualisasi tingkat kekumuhan sesuai indikator yang berlaku. Hasilnya dapat dimanfaatkan sebagai bahan perencanaan, monitoring, dan evaluasi lintas perangkat daerah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1557042);
