INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64421330', 64421330, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI PERENCANAAN PEMBANGUNAN', 'Penyediaan Jasa Konsultansi Perorangan Analis Sistem Pengendaian 5', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 70950000, 'January 2026', 'APBD', 1, 1, '1 Paket', '"1. Melakukan penyusunan dokumen Software Development Life Cycle (SDLC) yang memuat planning, design, testing, building, dan deployment. 2. Melakukan analisis kebutuhan pengembangan sistem informasi sesuai dengan proses bisnis yang diajukan oleh pengguna. 3. Melakukan penyusunan konsep, spesifikasi sistem informasi dan kebutuhan integrasi dengan sistem informasi lainnya. 4. Melakukan perancangan desain input, desain proses, serta desain output sistem informasi. 5. Melakukan analisis kebutuhan penyajian data antarmuka untuk modul yang akan dikembangkan. 6. Melakukan koordinasi dan pengelolaan tugas para tim developer sistem informasi. 7. Melakukan penyusunan dokumentasi teknis hasil kajian, analisis, dan konsep rancangan sistem. 8. Melakukan pendampingan, pelatihan serta dukungan teknis kepada pengguna sistem. 9. Membuat laporan sesuai tahapan pelaksanaan pekerjaan termasuk pendampingan dan konsultasi."', 'Tenaga Ahli Tidak Ber SKA / SKK , S1 Pengalaman Minimal 5 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1559272);
